// ---------------------------------------------------------------------------
// NutriPlan Food Bank — standardized recipes.
//
// Every dish lists the RAW ingredient weights (g, or ml for liquids) for ONE
// unit (1 roti, 1 katori, 1 idli …), including cooking oil and salt as used in
// healthy home cooking. Nutrition is computed from IFCT 2017 ingredient data
// (see ingredients.ts) — never typed in by hand — so values stay auditable.
//
// To extend the bank, add a dish here (or create a custom dish in the app).
// ---------------------------------------------------------------------------

import type { MealTime } from "../types";
