// ---- unit helpers ---------------------------------------------------------
const katori = (def = 1, note = "≈150 g cooked"): DishUnit => ({ label: "katori", plural: "katoris", default: def, step: 0.5, min: 0.5, max: 2.5, note });
const bowl = (def = 1, note = "≈250 ml"): DishUnit => ({ label: "bowl", plural: "bowls", default: def, step: 0.5, min: 0.5, max: 2, note });
const plate = (def = 1, note?: string): DishUnit => ({ label: "plate", plural: "plates", default: def, step: 0.5, min: 0.5, max: 2, note });
const glass = (note = "≈250 ml"): DishUnit => ({ label: "glass", plural: "glasses", default: 1, step: 0.5, min: 0.5, max: 2, note });
const cup = (note = "≈150 ml"): DishUnit => ({ label: "cup", plural: "cups", default: 1, step: 0.5, min: 0.5, max: 2, note });
const serving = (note?: string, def = 1): DishUnit => ({ label: "serving", plural: "servings", default: def, step: 0.5, min: 0.5, max: 2, note });
const pcs = (label: string, plural: string, def: number, min: number, max: number, note?: string): DishUnit => ({ label, plural, default: def, step: 1, min, max, note });

